#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int val = min({i, j, n - i + 1, n - j + 1});
            cout << val << (j == n ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
